/* Nitya Bhakti site language switcher. NITYA_D (the dictionary) is prepended at build time. */
(function(){
var LANGS=[['en','English'],['hi','हिन्दी'],['te','తెలుగు'],['ta','தமிழ்'],['kn','ಕನ್ನಡ'],['bn','বাংলা'],['ml','മലയാളം'],['pa','ਪੰਜਾਬੀ'],['mr','मराठी'],['gu','ગુજરાતી'],['ur','اردو']];
/* Languages whose readers get the verse in their own script: the separate
   transliteration row is then redundant, so it is hidden. For en/hi/mr/ur the
   Roman (IAST) transliteration row stays. */
var HIDE_TL={te:1,ta:1,kn:1,ml:1,bn:1,gu:1,pa:1};
var D=window.NITYA_D||{};
function cur(){try{var u=new URLSearchParams(location.search).get('lang');if(u&&D[u])return u;var l=localStorage.getItem('nitya-lang');return (l&&D[l])?l:'en';}catch(e){return 'en';}}
function t(k){var l=cur();return (D[l]&&D[l][k])||(D.en&&D.en[k])||null;}
function nativeName(l){var f=LANGS.find(function(x){return x[0]===l;});return f?f[1]:l;}
window.NITYA_T=t;window.NITYA_LANG=cur;window.NITYA_LANGS=LANGS;window.NITYA_NATIVE=nativeName;
var CACH={};
function escH(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function contentBase(){var s=document.querySelector('script[src*="i18n.js"]');if(!s)return '';var u=s.src;return u.slice(0,u.lastIndexOf('/')+1);}
function syncMeanToggle(l){var b=document.querySelector('.lang-toggle [data-lang="'+(l==='hi'?'hi':'en')+'"]');if(b&&!b.classList.contains('on'))b.click();}
/* ---- translated content (meanings, blurbs, titles): files i18n-content/<ns>-<lang>.json ---- */
function renderContent(l,n){var d=CACH[l+':'+n]||{};var mt=(D[l]&&D[l]['content.mt'])||'AI translation';
 document.querySelectorAll('[data-i18n-content]').forEach(function(el){var key=el.getAttribute('data-i18n-content');if(key.split(':')[0]!==n)return;
  if(l==='hi'&&el.getAttribute('data-mean')==='en')return; /* verse pages: Hindi shows via the en/hi pane toggle */
  var tv=d[key.slice(n.length+1)];
  if(tv){el.innerHTML=escH(tv)+((l==='hi'||el.getAttribute('data-mt')==='0')?'':'<br><span class="mt-note">- '+escH(mt)+'</span>');}
  else if(el._origHTML!=null){el.innerHTML=el._origHTML;}});}
function applyContent(l){
 var els=document.querySelectorAll('[data-i18n-content]');
 if(!els.length)return;
 els.forEach(function(el){if(el._origHTML==null)el._origHTML=el.innerHTML;});
 if(l==='en'){els.forEach(function(el){el.innerHTML=el._origHTML;});syncMeanToggle(l);return;}
 var ns={};els.forEach(function(el){if(l==='hi'&&el.getAttribute('data-mean')==='en')return;ns[el.getAttribute('data-i18n-content').split(':')[0]]=1;});
 Object.keys(ns).forEach(function(n){
  if(CACH[l+':'+n]){renderContent(l,n);return;}
  fetch(contentBase()+'i18n-content/'+n+'-'+l+'.json').then(function(r){return r.ok?r.json():{};}).then(function(d){CACH[l+':'+n]=d;renderContent(l,n);}).catch(function(){});});
 syncMeanToggle(l);}
/* ---- scripture in the reader's script: files i18n-content/gs-<lang>-ch<n>.json ---- */
function renderScript(l,f){var d=CACH[l+':'+f]||{};
 document.querySelectorAll('[data-i18n-script]').forEach(function(el){
  var cv=el.getAttribute('data-i18n-script').slice(3);var ch=cv.split('.')[0];
  if(('gs-'+l+'-ch'+ch)!==f)return;
  var tv=d[cv];
  if(tv){var txt=(el.getAttribute('data-part')==='f')?tv.f:tv.t;if(txt)el.innerHTML=escH(txt).replace(/\n/g,'<br>');}
  else if(el._origHTML!=null){el.innerHTML=el._origHTML;}});}
function applyScript(l){
 var els=document.querySelectorAll('[data-i18n-script]');
 var tls=document.querySelectorAll('[data-i18n-translit]');
 tls.forEach(function(el){el.style.display=HIDE_TL[l]?'none':'';});
 if(!els.length)return;
 els.forEach(function(el){if(el._origHTML==null)el._origHTML=el.innerHTML;});
 if(l==='en'||l==='hi'||l==='mr'){els.forEach(function(el){el.innerHTML=el._origHTML;});return;}
 var files={};els.forEach(function(el){files['gs-'+l+'-ch'+el.getAttribute('data-i18n-script').slice(3).split('.')[0]]=1;});
 Object.keys(files).forEach(function(f){
  if(CACH[l+':'+f]){renderScript(l,f);return;}
  fetch(contentBase()+'i18n-content/'+f+'.json').then(function(r){return r.ok?r.json():{};}).then(function(d){CACH[l+':'+f]=d;renderScript(l,f);}).catch(function(){});});}
function apply(l,save){
 if(!D[l])l='en';
 if(save){try{localStorage.setItem('nitya-lang',l);}catch(e){}}
 document.documentElement.lang=l;
 document.documentElement.dir=(l==='ur')?'rtl':'ltr';
 document.querySelectorAll('[data-i18n]').forEach(function(el){var v=(D[l]&&D[l][el.getAttribute('data-i18n')])||(D.en&&D.en[el.getAttribute('data-i18n')]);if(v!=null)el.textContent=v;});
 document.querySelectorAll('[data-i18n-ph]').forEach(function(el){var v=(D[l]&&D[l][el.getAttribute('data-i18n-ph')])||(D.en&&D.en[el.getAttribute('data-i18n-ph')]);if(v!=null)el.setAttribute('placeholder',v);});
 var lbl=document.getElementById('langcur');if(lbl)lbl.textContent=l.toUpperCase();
 document.querySelectorAll('.langopt').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-lang')===l);});
 try{applyContent(l);}catch(e){}
 try{applyScript(l);}catch(e){}
 try{window.dispatchEvent(new CustomEvent('nitya:lang',{detail:{lang:l}}));}catch(e){}
}
window.NITYA_SETLANG=apply;
document.addEventListener('DOMContentLoaded',function(){
 var btn=document.getElementById('langbtn'),panel=document.getElementById('langpanel');
 if(btn&&panel){
  LANGS.forEach(function(x){var b=document.createElement('button');b.type='button';b.className='langopt';b.setAttribute('data-lang',x[0]);b.textContent=x[1];b.addEventListener('click',function(){apply(x[0],true);panel.classList.remove('open');btn.setAttribute('aria-expanded','false');});panel.appendChild(b);});
  btn.addEventListener('click',function(e){e.stopPropagation();panel.classList.toggle('open');btn.setAttribute('aria-expanded',panel.classList.contains('open'));});
  document.addEventListener('click',function(e){if(!panel.contains(e.target)&&!btn.contains(e.target))panel.classList.remove('open');});
 }
 apply(cur(),false);
});
})();
